const IntrinsicFreeze = Object.freeze;
const IntrinsicApply = Reflect.apply;
const IntrinsicNow = Date.now;
const IntrinsicSetTimeout = globalThis.setTimeout;
const IntrinsicClearTimeout = globalThis.clearTimeout;
export const systemTaskDeadlineClock = IntrinsicFreeze({
    now: () => IntrinsicNow(),
    setTimer: (callback, delayMs) => IntrinsicSetTimeout(callback, delayMs),
    clearTimer: (handle) => IntrinsicClearTimeout(handle),
});
/** Snapshot the trusted constructor dependency before any project operation executes. */
export function snapshotTaskDeadlineClock(clock) {
    const now = clock.now;
    const setTimer = clock.setTimer;
    const clearTimer = clock.clearTimer;
    return IntrinsicFreeze({
        now: () => IntrinsicApply(now, clock, []),
        setTimer: (callback, delayMs) => IntrinsicApply(setTimer, clock, [callback, delayMs]),
        clearTimer: (handle) => IntrinsicApply(clearTimer, clock, [handle]),
    });
}
